// ── Index et contrat d'identifiants (exportés pour Manus, voir contrat-audio.ts) ──

export const IDS_TTS: readonly string[] = MESSAGES_TTS.map((m) => m.id);
export const IDS_INTENTS: readonly string[] = INTENTIONS_STT.map((i) => i.id);

const INDEX_TTS: ReadonlyMap<string, EntreeTts> = new Map(MESSAGES_TTS.map((m) => [m.id, m]));
const INDEX_INTENTS: ReadonlyMap<string, EntreeIntent> = new Map(INTENTIONS_STT.map((i) => [i.id, i]));

export function entreeTts(id: string): EntreeTts | undefined { return INDEX_TTS.get(id); }
export function entreeIntent(id: string): EntreeIntent | undefined { return INDEX_INTENTS.get(id); }

/** Les intentions dont une variante mal validée pourrait écrire de l'argent. */
export const INTENTS_CRITIQUES: readonly string[] = INTENTIONS_STT.filter((i) => i.critiqueArgent).map((i) => i.id);
/** Les messages qui décrivent ou déclenchent de l'argent : jamais servis depuis un brouillon. */
export const MESSAGES_CRITIQUES: readonly string[] = MESSAGES_TTS.filter((m) => m.critiqueArgent).map((m) => m.id);
